SELECT 'core-2026-09-v4','past-simple','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"past-simple","title":"Past simple","level":"A2","order":26,"summary":"Use regular and irregular past forms and keep the base verb after did.","learningGoals":["Completed past events","Questions and negatives","Spelling and unchanged forms"],"guidance":"Read the short rules and examples, then complete a 20-question session. Use feedback to explain each choice. Revisit the skill you missed before trying again.","rules":[{"title":"Completed past events","explanation":"Use the past simple for events at a finished past time. Regular forms often end in -ed; irregular forms must be learned.","examples":["We booked a room last week.","The visitor spoke to the guide."]},{"title":"Questions and negatives","explanation":"Did and did not carry the past tense. The main verb is the base form, even when its affirmative past is irregular.","examples":["Did the shop open early?","They did not bring a camera."]},{"title":"Spelling and unchanged forms","explanation":"Some verbs change spelling; others keep the same written form. Read has the same spelling in the present and past but different pronunciation.","examples":["carry → carried","put → put"]}],"tips":["Read the full context before choosing.","Check the explanation, including after a correct answer.","A passing practice session is useful feedback, not a language certificate."],"source":"seed","provenance":{"version":"foundations-2026-09-v1","authorship":"Grammacho; generated offline with AI assistance","kind":"original-guidance-aligned","reviewStatus":"automated-checked; educator-review-pending","referenceIds":["bc-past","pcc-esol"],"assessment":"Practice only; levels are approximate teaching labels, not validated CEFR assessment."},"chapter":{"introduction":["The past simple places an event or state in a finished past period. The time may be explicit, such as yesterday, or understood from the conversation. It is useful for a sequence of completed events in a story. Most subjects share the same past form; be is a major exception with was and were."],"rules":[{"title":"Completed past events","explanation":"Use the past simple for events at a finished past time. Regular forms often end in -ed; irregular forms must be learned.","examples":["We booked a room last week.","The visitor spoke to the guide.","We **arrived**, **unpacked** and **went** out."],"pattern":"work → work**ed** · go → **went**","paragraphs":["Regular verbs commonly add -ed, but irregular verbs must be learned individually: take → took, buy → bought, write → wrote. A past form does not need have before it. She wrote yesterday is past simple; she has written is a different construction."],"id":"past-simple-foundation-1","domain":"verbs","referenceIds":["bc-past","pcc-esol"],"readingVersion":"foundations-2026-09-v1"},{"title":"Questions and negatives","explanation":"Did and did not carry the past tense. The main verb is the base form, even when its affirmative past is irregular.","examples":["Did the shop open early?","They did not bring a camera.","**Did** they **bring** the map?"],"pattern":"**Did** she **go**? / She **did not go**.","paragraphs":["Did carries the past tense in questions and negatives. Return the lexical verb to its base even if it is irregular: Did she go?, not Did she went? Be forms its own questions and negatives: Was she there? She wasn’t there."],"id":"past-simple-foundation-2","domain":"verbs","referenceIds":["bc-past","pcc-esol"],"readingVersion":"foundations-2026-09-v1"},{"title":"Spelling and unchanged forms","explanation":"Some verbs change spelling; others keep the same written form. Read has the same spelling in the present and past but different pronunciation.","examples":["carry → carried","put → put","They **didn’t bring** it, so we **bought** one."],"pattern":"carry → carr**ied** · stop → sto**pped** · put → **put**","paragraphs":["Some forms look unchanged, such as cut and put. Read keeps its spelling but its past pronunciation rhymes with red. Regular -ed has several pronunciations; the spelling alone does not imply an extra spoken syllable."],"id":"past-simple-foundation-3","domain":"verbs","referenceIds":["bc-past","pcc-esol"],"readingVersion":"foundations-2026-09-v1"},{"title":"Contrasts and edge cases","explanation":"Past simple can describe past states as well as actions: I knew her at school. In a story, past continuous often gives the background while past simple advances the sequence. Present perfect instead connects earlier events with now; a finished date normally favours past simple.","examples":["We **arrived**, **unpacked** and **went** out.","**Did** they **bring** the map?","They **didn’t bring** it, so we **bought** one."],"id":"past-simple-foundation-4","domain":"verbs","referenceIds":["bc-past","pcc-esol"],"readingVersion":"foundations-2026-09-v1"}],"recap":["work → work**ed** · go → **went**","**Did** she **go**? / She **did not go**.","carry → carr**ied** · stop → sto**pped** · put → **put**"],"readingVersion":"core-2026-09-v4"},"stage":"3 · Time and experience","prerequisites":["modals-ability"],"readingReferenceIds":["bc-past","pcc-esol"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='past-simple'
